mapper.select:
SELECT id, site_id, user_id, session_id, ip_hash, user_agent, referrer, page_url, status_code, response_time_ms, created_at FROM access_log
AND created_at >= #{req.from}::date
AND created_at < #{req.to}::date + INTERVAL '1 day'
AND status_code = #{req.statusCode}
AND page_url ILIKE '%' || #{req.pageUrl} || '%'
ORDER BY created_at DESC LIMIT #{req.size} OFFSET #{req.offset}
